function floatTo16BitPCM(float32Array) {
	const int16Array = new Int16Array(float32Array.length);
	for (let i = 0; i < float32Array.length; i++) {
		const s = Math.max(-1, Math.min(1, float32Array[i]));
		int16Array[i] = s < 0 ? s * 32768 : s * 32767;
	}
	return int16Array;
}
function float32ToBase64PCM(float32Array) {
	const int16Array = floatTo16BitPCM(float32Array);
	const bytes = new Uint8Array(int16Array.buffer);
	let binary = "";
	const chunkSize = 8192;
	for (let i = 0; i < bytes.length; i += chunkSize) binary += String.fromCharCode.apply(null, Array.from(bytes.subarray(i, i + chunkSize)));
	return btoa(binary);
}
function base64ToFloat32(base64String) {
	const binaryString = atob(base64String);
	const len = binaryString.length;
	const bytes = new Uint8Array(len);
	for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);
	const int16Array = new Int16Array(bytes.buffer);
	const float32Array = new Float32Array(int16Array.length);
	for (let i = 0; i < int16Array.length; i++) float32Array[i] = int16Array[i] / 32768;
	return float32Array;
}
function downsampleTo16000(float32Array, inputSampleRate) {
	if (inputSampleRate === 16e3) return float32Array;
	const compression = inputSampleRate / 16e3;
	const length = Math.floor(float32Array.length / compression);
	const result = new Float32Array(length);
	let index = 0;
	let inputIndex = 0;
	while (index < length) {
		result[index] = float32Array[Math.floor(inputIndex)];
		inputIndex += compression;
		index++;
	}
	return result;
}
