var ingestCodebase = async (dirPath) => {
	try {
		const geminiKey = localStorage.getItem("iris_custom_api_key") || "";
		if (!geminiKey.trim()) throw new Error("Missing Gemini API Key. Please update it in the Command Center Vault.");
		window.dispatchEvent(new CustomEvent("oracle-ingest-start", { detail: { path: dirPath } }));
		const cleanupListener = window.electron.ipcRenderer.on("oracle-progress", (_ipcEvent, data) => {
			const payload = data || _ipcEvent;
			window.dispatchEvent(new CustomEvent("oracle-progress", { detail: payload }));
		});
		const result = await window.electron.ipcRenderer.invoke("ingest-codebase", {
			dirPath,
			geminiKey
		});
		if (typeof cleanupListener === "function") cleanupListener();
		if (result.success) {
			window.dispatchEvent(new CustomEvent("oracle-ingest-done", { detail: { chunks: result.totalChunks } }));
			return result.wasResumed ? `✅ Successfully resumed and completed ingestion. Memory Banks fully loaded.` : `✅ Successfully ingested directory. Generated ${result.totalChunks} vectors.`;
		}
		return `❌ Ingestion Aborted or Failed: ${result.error}`;
	} catch (error) {
		return `❌ System failure: ${String(error)}`;
	}
};
