var analyzeDirectPhoto = async (filePath, socket) => {
	try {
		const url = `file:///${filePath.replace(/\\/g, "/")}`;
		const blob = await (await fetch(url)).blob();
		const reader = new FileReader();
		return new Promise((resolve) => {
			reader.onloadend = () => {
				const base64data = reader.result.split(",")[1];
				if (socket && socket.readyState === WebSocket.OPEN) {
					socket.send(JSON.stringify({ realtimeInput: { mediaChunks: [{
						mimeType: "image/png",
						data: base64data
					}] } }));
					resolve("✅ Photo successfully injected into your vision. You can now see it. Describe what you see to Harsh.");
				} else resolve("❌ Failed: Connection not open.");
			};
			reader.readAsDataURL(blob);
		});
	} catch (e) {
		return "❌ Error loading direct photo.";
	}
};
